from pathlib import Path
import re,json,html,shutil,hashlib
src=Path('content'); out=Path('.'); (out/'research').mkdir(exist_ok=True)
esc=html.escape
pubs=json.loads(Path('publications.json').read_text())
base=(src/'index.html').read_text()

def extract(s,tag,cls):
 return re.search(r'<'+tag+r'[^>]*class="'+cls+r'"[^>]*>.*?</'+tag+r'>',s,re.S).group()
def shell(title,body,depth='',active=''):
 style_version=hashlib.sha256((out/'assets/redesign.css').read_bytes()).hexdigest()[:12]
 script_version=hashlib.sha256((out/'assets/site.js').read_bytes()).hexdigest()[:12]
 nav=''.join(f'<a href="{depth}{url}" '+('aria-current="page"' if label==active else '')+f'>{label}</a>' for label,url in [('Research','index.html#research'),('Publications','publications.html'),('Experience','index.html#experience'),('CV','cv.html')])
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | Raoof Zare Moayedi</title><meta name="description" content="Raoof Zare Moayedi — machine learning research in privacy, robustness, and scientific learning."><meta name="theme-color" content="#0b0e14"><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' rx='12' fill='%2338549e'/%3E%3Ctext x='20' y='29' fill='white' font-style='italic' font-size='32' text-anchor='middle' font-family='serif'%3Er%3C/text%3E%3C/svg%3E"><script>try{{document.documentElement.dataset.theme=localStorage.getItem('theme')||'dark'}}catch(e){{}}</script><link rel="stylesheet" href="{depth}assets/site.css"><link rel="stylesheet" href="{depth}assets/redesign.css?v={style_version}"><script src="{depth}assets/site.js?v={script_version}" defer></script></head><body><a class="skip" href="#main">Skip to content</a><div class="progress" aria-hidden="true"></div><header class="header"><nav class="nav wrap" aria-label="Main navigation"><a class="brand" href="{depth}index.html"><span class="monogram" aria-hidden="true">r</span><span class="brand-name"><strong>Raoof</strong><span>Zare Moayedi</span></span></a><div class="nav-right"><button class="menu-button" aria-label="Toggle navigation" aria-expanded="false" aria-controls="navigation">Menu</button><div class="nav-links" id="navigation">{nav}</div><button class="theme-button" aria-label="Switch to light theme" title="Change color theme">◐</button></div></nav></header><main id="main" class="wrap">{body}</main><footer class="footer"><div class="wrap"><a href="{depth}index.html">Raoof Zare Moayedi</a><span>Machine learning · September 2026</span><a href="#main">Back to top</a></div></footer><div class="toast" role="status" aria-live="polite"></div></body></html>'''
hero='''<section class="hero" id="about"><div class="hero-copy"><p class="eyebrow"><span class="tiny-line"></span> Machine learning researcher</p><h1>Raoof<br>Zare Moayedi<span class="name-dot">.</span></h1><p class="hero-lead">Understanding learning.<br><em>Building trust.</em></p><p class="hero-description">I study how the structure of data and the dynamics of training shape what machine learning can guarantee.</p><div class="hero-actions"><a class="button primary" href="#research">Explore my research</a><a class="button secondary" href="cv.html">Curriculum vitae</a></div><p class="hero-affiliation">M.Sc. Computer Science <span>Sharif University of Technology</span></p></div><div class="research-art sketch-panel"><div class="sketch-paper"><img class="hero-sketch sketch-scene" data-sketch="0" src="assets/privacy-sketch.webp" alt="A little researcher studies the geometry of protected data and a similar group of synthetic points." width="1536" height="1024" decoding="async"><img class="hero-sketch sketch-scene" data-sketch="1" src="assets/robustness-sketch.webp" alt="A teacher model helps a smaller student learn while perturbations swirl around them." width="1536" height="1024" hidden decoding="async"><img class="hero-sketch sketch-scene" data-sketch="2" src="assets/unlearning-sketch.webp" alt="A friendly eraser removes one selected memory while preserving the rest of a connected scrapbook." width="1536" height="1024" hidden decoding="async"></div><div class="art-bottom"><div class="art-tabs" role="group" aria-label="Explore research interests"><button aria-pressed="true" data-landscape="0">Privacy</button><button aria-pressed="false" data-landscape="1">Robustness</button><button aria-pressed="false" data-landscape="2">Unlearning</button></div><p id="art-description" aria-live="polite">Private synthetic data that adapts to the geometry of the original data.</p></div></div></section>'''
interest_groups=[
 ('Learning foundations',['Robust statistics','Uncertainty quantification','Training dynamics']),
 ('Trustworthy learning',['Differential privacy','Robust machine learning','Machine unlearning']),
 ('Reasoning & science',['LLM reasoning','Scientific deep learning'])
]
interest_columns=''.join(f'<article class="interest-group"><p class="interest-number" aria-hidden="true">0{i+1}</p><h3>{esc(title)}</h3><ul>'+''.join(f'<li>{esc(topic)}</li>' for topic in topics)+'</ul></article>' for i,(title,topics) in enumerate(interest_groups))
interests=f'<section class="section interests-section" id="interests" aria-labelledby="interests-title"><div class="section-heading reveal"><div><p class="eyebrow">01 / Research directions</p><h2 id="interests-title">Research interests.</h2></div><p class="section-aside interests-intro">From statistical foundations to reliable learning and reasoning.</p></div><div class="interest-grid reveal">{interest_columns}</div></section>'
selected=[pubs[4],pubs[0],pubs[1],pubs[3],pubs[2],pubs[5]]
shorts=['Geometry-adaptive private synthetic data','Teaching robustness with inverse adversaries','Learning smoother physical systems','Private Gaussian multi-sampling','Private covariance across data holders','When SGD learns beyond shortcuts']
topics=['Differential privacy','Robust learning','Scientific ML','Private sampling','Covariance estimation','SGD & robustness']
summaries=['Privacy guarantees that adapt to the geometry of the data.','Transferring robustness from a teacher model to a student.','Improving physics-informed networks through residual curvature.','Generating private Gaussian samples with guarantees for the whole batch.','Estimating relationships between features held by separate parties, with private releases.','Understanding early training dynamics and small-batch warmup for robustness to spurious correlations.']
artworks=['privacy-sketch.webp','robustness-sketch.webp','scientific-sketch.webp','sampling-sketch.webp','covariance-sketch.webp','sgd-sketch.webp']
alts=['A curious little researcher examines protected data and similar synthetic points.','A teacher and student learn together as papers swirl around them.','A little scientist rolls a wrinkled surface smooth while a cheerful droplet watches.','A little statistician scoops sample marbles from a bell-shaped jar into a tray.','Two private data holders contribute complementary feature tables while an analyst assembles a matrix.','A little explorer follows small stepping stones and then larger ones, avoiding an unreliable shortcut.']
venues=['PREPRINT','IEEE TPAMI','CMAME','PREPRINT','PREPRINT','UNDER REVIEW']
cards=''
for i,p in enumerate(selected):
 cards+=f'''<article class="work-card reveal"><div class="card-meta"><span>{topics[i]}</span><span>0{i+1}</span></div><a class="research-illustration" href="{p['project']}" aria-label="Explore {esc(shorts[i])}"><img src="assets/{artworks[i]}" alt="{alts[i]}" width="1536" height="1024" loading="lazy" decoding="async"></a><p class="card-venue">{p['year']} / {venues[i]}</p><h3><a href="{p['project']}">{shorts[i]}</a></h3><p>{summaries[i]}</p><a class="card-link" href="{p['project']}">Explore research <span aria-hidden="true">+</span></a></article>'''
research=f'<section class="section" id="research"><div class="section-heading reveal"><div><p class="eyebrow">02 / Selected work</p><h2>Selected research.</h2></div><a class="text-link" href="publications.html">All 7 publications</a></div><div class="work-grid">{cards}</div></section>'
exp=re.search(r'<div class="experience-list">(.*?)</div></section>',base,re.S).group(1)
rows=re.findall(r'<article class="institution-row">(.*?)</article>',exp,re.S)
experience='<section class="section experience-section" id="experience"><div class="section-heading reveal"><div><p class="eyebrow">03 / Research journey</p><h2>Research journey.</h2></div><p class="section-aside">Across theory, learning algorithms,<br>and real-world systems.</p></div><div class="timeline">'
for i,row in enumerate(rows):
 h=re.search(r'<h3>(.*?)</h3>',row).group(1);role=re.search(r'<p class="position-role">(.*?)</p>',row).group(1);date=re.search(r'<p class="position-date">(.*?)</p>',row).group(1);desc=re.search(r'<div class="institution-description">(.*)</div>',row,re.S).group(1)
 experience+=f'<details class="journey reveal" '+('open' if i==0 else '')+f'><summary><span class="journey-date">{date}</span><span class="journey-name">{h}<small>{role}</small></span><span class="expand" aria-hidden="true">+</span></summary><div class="journey-description">{desc}</div></details>'
experience+='</div></section>'
education=f'''<section id="education" class="section"><div class="section-heading"><div><p class="eyebrow">04 / Foundations</p><h2>Education</h2></div><a class="text-link" href="cv.html">Full CV</a></div><div class="education-list">
<article class="education-row"><div class="education-copy"><h3>Sharif University of Technology</h3><div class="degree-record"><p class="degree-name">M.Sc. in Computer Science</p><p class="position-date">2024 – present</p><dl class="academic-record"><div><dt>GPA</dt><dd>19.7<span> / 20</span></dd></div><div><dt>Class rank</dt><dd>1st<span> · ongoing</span></dd></div></dl></div></div></article>
<article class="education-row"><div class="education-copy"><h3>Amirkabir University of Technology</h3><div class="degree-record"><p class="degree-name">B.Sc. in Computer Science</p><p class="position-date">2018 – 2023</p><dl class="academic-record"><div><dt>GPA</dt><dd>18.82<span> / 20</span></dd></div><div><dt>Graduating class rank</dt><dd>3rd</dd></div></dl></div><div class="degree-record"><p class="degree-name">B.Sc. in Mathematics</p><p class="position-date">2019 – 2023</p><dl class="academic-record"><div><dt>GPA</dt><dd>18.99<span> / 20</span></dd></div><div><dt>Graduating class rank</dt><dd>2nd</dd></div></dl></div></div></article></div></section>'''
contact='''<section class="contact-panel reveal" id="contact"><p class="eyebrow">Let’s connect</p><h2>Let’s talk research.</h2><div class="contact-actions"><a class="button primary" href="mailto:Raoofmoayedi2000@gmail.com">Get in touch</a><button class="button secondary" data-copy="Raoofmoayedi2000@gmail.com">Copy email</button><a class="text-link" href="https://github.com/raoofmoayedi">GitHub</a></div><a class="email-address" href="mailto:Raoofmoayedi2000@gmail.com">Raoofmoayedi2000@gmail.com</a></section>'''
(out/'index.html').write_text(shell('Machine Learning Research',hero+interests+research+experience+education+contact))
# Keep the complete academic record and research explanations.
for path in [Path('cv.html'),*Path('content/research').glob('*.html')]:
 rel=path if path.name=='cv.html' else Path('research')/path.name
 raw=(src/rel).read_text();body=re.search(r'<main[^>]*>(.*)</main>',raw,re.S).group(1);title=re.search('<title>(.*?)</title>',raw).group(1).split(' | ')[0]
 (out/rel).write_text(shell(title,body,'../' if rel.parent.name=='research' else '', 'CV' if rel.name=='cv.html' else 'Research'))
# Publication cards stay fully readable without JavaScript.
body='''<header class="page-hero"><p class="eyebrow">Research library</p><h1>Publications<span class="name-dot">.</span></h1><p>Privacy, robustness, and the foundations of learning.</p></header><section class="publication-page"><div class="publication-tools"><label class="search-field"><span class="sr-only">Search publications</span><input id="paper-search" type="search" placeholder="Search by title, author, or topic…"></label><a class="text-link" href="papers.bib" download>Download BibTeX</a></div><div class="filter-row"><div class="filters" role="group" aria-label="Filter publications"><button class="filter" data-filter="all" aria-pressed="true">All work <span>7</span></button><button class="filter" data-filter="privacy" aria-pressed="false">Privacy</button><button class="filter" data-filter="robustness" aria-pressed="false">Robustness</button><button class="filter" data-filter="scientific" aria-pressed="false">Scientific ML</button></div><span id="result-count" role="status">7 publications</span></div><div id="paper-list">'''
bib=(src/'papers.bib').read_text(); entries=re.split(r'\n\n',bib.strip())
for i,p in enumerate(pubs):
 topic='privacy' if i in [2,3,4] else 'scientific' if i==1 else 'robustness'
 title=esc(p['title']);link=p.get('project',p.get('url',''))
 actions=(f'<a href="{p["url"]}" target="_blank" rel="noopener">Read paper</a>' if p.get('url') else '')+(f'<a href="{p["project"]}">Research details</a>' if p.get('project') else '')
 body+=f'''<article class="pub library-paper" data-topic="{topic}"><div class="pub-label"><span class="pub-year">{p['year']}</span><span class="paper-index">0{i+1}</span></div><div class="pub-content"><p class="paper-status">{esc(p['status'])} · {topic.title()}</p><h3><a href="{link}">{title}</a></h3><p class="pub-authors">{esc(', '.join(p['authors'])).replace('R. Zare Moayedi','<strong>R. Zare Moayedi</strong>')}</p><p class="pub-meta">{esc(p['venue'])}</p><div class="pub-actions">{actions}<details><summary>BibTeX</summary><pre>{esc(entries[i])}</pre><button class="copy-citation">Copy citation</button></details></div></div></article>'''
body+='</div><div id="empty-state" hidden><h2>No matching publications</h2><p>Try a different keyword or research topic.</p><button class="button secondary" id="reset-search">Clear filters</button></div><p class="pub-footer">* Equal contribution. Publication statuses follow the September 2026 record.</p></section>'
(out/'publications.html').write_text(shell('Publications',body,active='Publications'))
shutil.copy(src/'papers.bib',out/'papers.bib');shutil.copy(src/'assets/site.css',out/'assets/site.css')
(out/'404.html').write_text(shell('Page not found','<div class="page-hero"><p class="eyebrow">404</p><h1>A different direction.</h1><p>This page could not be found.</p><a class="button primary" href="/index.html">Back to research</a></div>'))
print('Generated 10 pages and bibliography.')
